-- Production price-only regression after manual 87-table archive deletion and 7-function retirement, 2026-10-30. READ ONLY.
WITH tests(test_name,passed) AS (
 SELECT '01_CRYPTO_CRON_ROUTED', (SELECT active AND command LIKE '%/functions/v1/price-market-refresh-v1%' AND command LIKE '%CRYPTO%' FROM cron.job WHERE jobid=14)
 UNION ALL SELECT '02_FX_CRON_ROUTED',(SELECT active AND command LIKE '%/functions/v1/price-market-refresh-v1%' AND command LIKE '%FX%' FROM cron.job WHERE jobid=15)
 UNION ALL SELECT '03_SHEET_CRON_ROUTED',(SELECT active AND command LIKE '%/functions/v1/price-sheet-sync-v1%' FROM cron.job WHERE jobid=16)
 UNION ALL SELECT '04_EOD_ENQUEUE_UNSCHEDULED',(SELECT count(*)=0 FROM cron.job WHERE jobid=6)
 UNION ALL SELECT '05_EOD_WORKER_UNSCHEDULED',(SELECT count(*)=0 FROM cron.job WHERE jobid=7)
 UNION ALL SELECT '06_NO_OLD_MTM_CRON',(SELECT count(*)=0 FROM cron.job WHERE active AND command LIKE '%/functions/v1/portfolio-mtm-refresh-v1%')
 UNION ALL SELECT '07_NATIVE_USD_CRYPTOS_PERSISTED',(SELECT count(DISTINCT instrument_id)>=6 FROM fwios.market_observations WHERE provider='COINGECKO' AND value_currency='USD' AND raw_payload->>'price_only'='true')
 UNION ALL SELECT '08_FX_PERSISTED',(SELECT count(*)>=1 FROM fwios.market_observations WHERE provider='FRANKFURTER_FX' AND fx_base_currency='USD' AND fx_quote_currency='THB')
 UNION ALL SELECT '09_CANONICAL_MARKET_OBSERVATIONS_PRESERVED',(SELECT count(*)>1000 FROM fwios.market_observations)
 UNION ALL SELECT '10_ARCHIVE_SCHEMA_DROPPED',(SELECT to_regnamespace('fwios_legacy_archive_20261029') IS NULL)
 UNION ALL SELECT '11_MTM_RUNS_DROPPED',(SELECT to_regclass('fwios.portfolio_mtm_runs') IS NULL)
 UNION ALL SELECT '12_PORTFOLIO_QUOTES_DROPPED',(SELECT to_regclass('fwios.portfolio_market_quote_snapshots') IS NULL)
 UNION ALL SELECT '13_SHEET_HOLDINGS_SNAPSHOTS_DROPPED',(SELECT to_regclass('fwios.portfolio_live_holdings_rows_v1') IS NULL)
 UNION ALL SELECT '14_SCENARIO_TABLES_DROPPED',(SELECT to_regclass('fwios.portfolio_scenario_runs') IS NULL)
 UNION ALL SELECT '15_TTWO_MODEL_CANDIDATES_DROPPED',(SELECT to_regclass('fwios.ai_model_candidates_v1') IS NULL)
 UNION ALL SELECT '16_OLD_LEDGER_GONE',(SELECT to_regclass('fwios_legacy_archive_20261029.portfolio_transactions') IS NULL)
 UNION ALL SELECT '17_OLD_PROVIDER_TABLE_GONE',(SELECT to_regclass('fwios_legacy_archive_20261029.decision_refresh_provider_registry') IS NULL)
 UNION ALL SELECT '18_PRICE_ONLY_JOB_UNIVERSE_NONTRADING',(SELECT count(*)=0 FROM cron.job WHERE active AND jobname ILIKE '%trade%')
 UNION ALL SELECT '19_LEGACY_PROVIDER_VALIDATOR_UNSCHEDULED',(SELECT count(*)=0 FROM cron.job WHERE jobid=5)
 UNION ALL SELECT '20_ONLY_PRICE_CRONS_ACTIVE',(SELECT count(*)=5 AND bool_and(active) AND count(*) FILTER(WHERE jobname IN('fwios-us-stock-eod-close-v1','fwios-us-stock-eod-sheet-followup-v1'))=2 FROM cron.job)
 UNION ALL SELECT '21_PRICE_SCHEMA_MINIMAL',(SELECT count(*)=5 FROM pg_class WHERE relnamespace='fwios'::regnamespace AND relkind IN ('r','p'))
 UNION ALL SELECT '22_ZERO_ARCHIVE_RELATIONS',(SELECT count(*)=0 FROM pg_class WHERE relnamespace=to_regnamespace('fwios_legacy_archive_20261029') AND relkind IN ('r','p'))
 UNION ALL SELECT '23_PRICE_IDENTITY_VIEW_RETAINED',(SELECT count(*)=1 FROM pg_class WHERE relnamespace='fwios'::regnamespace AND relkind IN ('v','m') AND relname='v_instrument_identity_current')
 UNION ALL SELECT '24_ONLY_SIX_PRICE_FUNCTIONS_REMAIN',(SELECT count(*)=6 FROM pg_proc WHERE pronamespace='fwios'::regnamespace)
 UNION ALL SELECT '25_OBSOLETE_SNAPSHOT_TRIGGER_GONE',(SELECT to_regprocedure('fwios.immutable_snapshot_guard_v1()') IS NULL)
 UNION ALL SELECT '26_SEVEN_LEGACY_SQL_ROUTINES_GONE',(SELECT count(*)=0 FROM pg_proc WHERE pronamespace='fwios'::regnamespace AND proname = ANY(ARRAY['immutable_snapshot_guard_v1','lineage_append_only_guard_v1','normalize_architecture_system_state_write_v1','sync_market_daily_close_observation_v1','sync_market_price_quote_observation_v1','sync_market_price_snapshot_observation_v1','thesis_memory_append_only_guard_v1']))
 UNION ALL SELECT '27_ONLY_FIVE_CRON_REGISTRATIONS',(SELECT count(*)=5 FROM cron.job)
 UNION ALL SELECT '28_US_STOCK_EOD_CRON_ROUTED',(SELECT active AND command LIKE '%/functions/v1/price-market-refresh-v1%' AND command LIKE '%US_STOCK_EOD%' AND schedule='0 0,23 * * *' FROM cron.job WHERE jobname='fwios-us-stock-eod-close-v1')
 UNION ALL SELECT '29_STOCK_SHEET_FOLLOWUP_CRON_ROUTED',(SELECT active AND command LIKE '%/functions/v1/price-sheet-sync-v1%' AND command LIKE '%STOCK_EOD_SHEET%' AND schedule='30 0,23 * * *' FROM cron.job WHERE jobname='fwios-us-stock-eod-sheet-followup-v1')
)
SELECT test_name,CASE WHEN passed IS TRUE THEN 'PASS' ELSE 'FAIL' END result FROM tests ORDER BY test_name;